import React, { useCallback, useEffect, useRef, useState } from 'react';

import OpenFin from '@openfin/core';

import { connectDropdownMenuChannel } from '@common/utils/enterprise-channels';
import { DropdownMenuChannelMessage, PopupWindowMenuType } from '@common/utils/popup-window';

import { AnchorBehavior } from '@client-platform/api/context-menu';

import { DropdownMenuResponseData } from '@enterprise/components/App/ContextMenu/DropdownMenu';

/*
 * This hook is used to manage the dropdown menu state and show the dropdown menu when the dropdown button is clicked.
 * @param dropdownButtonRef - The ref of the dropdown button.
 * @param dropdownOptions - The options to display in the dropdown menu.
 * @param onValueChange - The function to call when the dropdown value changes.
 * @param onDropdownBlurred - The function to call when the dropdown menu is blurred.
 */
export const useDropdownMenu = (
    dropdownButtonRef: React.MutableRefObject<HTMLButtonElement>,
    dropdownOptions: Array<OpenFin.MenuItemTemplate>,
    onValueChange: (response: any) => void,
    onDropdownBlurred?: () => void
) => {
    const [isShown, setIsShown] = useState(false);
    const [isChannelInitialized, setIsChannelInitialized] = useState(false);
    const channelRef = useRef<OpenFin.ChannelClient | null>(null);

    useEffect(() => {
        const initializeChannel = async () => {
            if (!channelRef.current) {
                channelRef.current = await connectDropdownMenuChannel();
                setIsChannelInitialized(true);
            }
        };

        initializeChannel();

        return () => {
            if (channelRef.current) {
                channelRef.current.disconnect();
                channelRef.current = null;
                setIsChannelInitialized(false);
            }
        };
    }, []);

    useEffect(() => {
        if (isChannelInitialized) {
            const registerHandlers = () => {
                channelRef.current?.register('response', (e: DropdownMenuResponseData) => {
                    if (e.type === 'dropdown-blurred') {
                        if (onDropdownBlurred) {
                            onDropdownBlurred();
                        }
                    }
                    if (e.type === 'value-changed') {
                        onValueChange(e.data);
                    }
                    (fin.me as OpenFin.Window).focus();
                    setIsShown(false);
                });
            };

            registerHandlers();

            return () => {
                if (channelRef.current) {
                    channelRef.current.remove('response');
                }
            };
        }
    }, [isChannelInitialized, onValueChange, onDropdownBlurred]);

    const showDropdown = useCallback(async () => {
        if (!dropdownButtonRef.current || !isChannelInitialized) {
            return;
        }

        setIsShown(true);

        const parentWindowBounds = await (await fin.Window.getCurrent()).getBounds();
        const dropdownIconRect = dropdownButtonRef.current.getBoundingClientRect();

        await channelRef.current?.dispatch('open', {
            parentIdentity: fin.me.identity,
            type: PopupWindowMenuType.DropdownMenu,
            anchorBehavior: AnchorBehavior.Center,
            responseIdentity: fin.me.identity,
            x: parentWindowBounds.left + dropdownIconRect.left,
            y: parentWindowBounds.top + dropdownIconRect.top + dropdownIconRect.height + 5,
            payload: { template: dropdownOptions, width: dropdownIconRect.width }
        } as DropdownMenuChannelMessage);
    }, [dropdownButtonRef, dropdownOptions, isChannelInitialized]);

    return {
        isShown,
        showDropdown
    };
};
